const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeUrmia = ee.Geometry.Point(45.45, 37.75).buffer(10000); // Point in Lake Urmia with 10km buffer

  const date1_start = '2016-07-18';
  const date1_end = '2016-07-19'; // Single day window
  const date2_start = '2016-04-23';
  const date2_end = '2016-04-24'; // Single day window

  const bandName = 'B4'; // Red band for Sentinel-2

  // Function to mask clouds and non-water pixels
  function maskS2Clouds(image) {
    const qa = image.select('SCL');
    // Pixels with SCL = 6 (water) are kept.
    // Pixels with SCL = 3 (cloud shadow), 8 (cloud medium prob), 9 (cloud high prob), 10 (cirrus) are masked.
    // SCL = 0 (No Data), 1 (Saturated or defective), 2 (Dark Area Pixels), 4 (Vegetation), 5 (Not vegetated), 7 (Unclassified), 11 (Snow/Ice)
    // We want to analyze water, so we explicitly select water (6) and mask out others that aren't water.
    // However, for "water redness", we just need to avoid clouds and land, so filtering for SCL=6 might be too strict if a significant portion isn't perfectly classified as water.
    // A more flexible approach is to mask clouds and then calculate over the remaining pixels that are likely water.
    // For now, let's focus on masking clouds and bad pixels.
    const cloud_mask = qa.neq(3).and(qa.neq(8)).and(qa.neq(9)).and(qa.neq(10));
    return image.updateMask(cloud_mask);
  }

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(lakeUrmia)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)) // Pre-filter for low cloudiness
    .map(maskS2Clouds);

  const col_jul18 = collection.filterDate(date1_start, date1_end);
  const col_apr23 = collection.filterDate(date2_start, date2_end);

  const size_jul18 = await col_jul18.size().getInfo();
  const size_apr23 = await col_apr23.size().getInfo();

  let img_jul18 = null;
  let img_apr23 = null;

  if (size_jul18 === 0) {
    // Try fallback: widen the date window for July 18
    const col_jul18_wide = collection.filterDate('2016-07-16', '2016-07-20'); // +/- 2 days
    if (await col_jul18_wide.size().getInfo() > 0) {
      img_jul18 = col_jul18_wide.first();
      console.log(`2016-07-18 Images: 0 (Using first image from 2016-07-16 to 2016-07-20)`);
    } else {
      console.log('2016-07-18 Images: 0');
    }
  } else {
    img_jul18 = col_jul18.first();
    console.log(`2016-07-18 Images: ${size_jul18}`);
  }

  if (size_apr23 === 0) {
    // Try fallback: widen the date window for April 23
    const col_apr23_wide = collection.filterDate('2016-04-21', '2016-04-25'); // +/- 2 days
    if (await col_apr23_wide.size().getInfo() > 0) {
      img_apr23 = col_apr23_wide.first();
      console.log(`2016-04-23 Images: 0 (Using first image from 2016-04-21 to 2016-04-25)`);
    } else {
      console.log('2016-04-23 Images: 0');
    }
  } else {
    img_apr23 = col_apr23.first();
    console.log(`2016-04-23 Images: ${size_apr23}`);
  }

  if (!img_jul18 || !img_apr23) {
    console.log('Not enough images for comparison.');
    console.log('C1');
    return;
  }

  // 3. Processing (Calculate pixel count to detect C2)
  const scale = 100; // 100m scale for aggregation

  const count_jul18_obj = await img_jul18.select(bandName).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeUrmia,
    scale: scale,
    maxPixels: 1e9,
  }).get(bandName).getInfo();

  const count_apr23_obj = await img_apr23.select(bandName).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeUrmia,
    scale: scale,
    maxPixels: 1e9,
  }).get(bandName).getInfo();

  const count_jul18 = count_jul18_obj || 0;
  const count_apr23 = count_apr23_obj || 0;

  if (count_jul18 === 0 || count_apr23 === 0) {
    console.log(`Valid pixels July 18: ${count_jul18}, April 23: ${count_apr23}`);
    console.log('No valid pixels after masking for one or both dates.');
    console.log('C2');
    return;
  }

  // 4. Calculation
  const redness_jul18_obj = await img_jul18.select(bandName).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: lakeUrmia,
    scale: scale,
    maxPixels: 1e9,
  }).get(bandName).getInfo();

  const redness_apr23_obj = await img_apr23.select(bandName).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: lakeUrmia,
    scale: scale,
    maxPixels: 1e9,
  }).get(bandName).getInfo();

  const redness_jul18 = redness_jul18_obj;
  const redness_apr23 = redness_apr23_obj;

  // 5. Validation & Final Answer
  if (redness_jul18 === null || redness_jul18 === undefined ||
      redness_apr23 === null || redness_apr23 === undefined ||
      isNaN(redness_jul18) || isNaN(redness_apr23)) {
    console.log('Redness calculation resulted in null/NaN for one or both dates.');
    console.log('C3');
    return;
  }

  console.log(`July 18, 2016 Redness (B4): ${redness_jul18.toFixed(2)} (Pixels: ${count_jul18})`);
  console.log(`April 23, 2016 Redness (B4): ${redness_apr23.toFixed(2)} (Pixels: ${count_apr23})`);

  if (redness_jul18 < redness_apr23) {
    console.log('A'); // Yes, Lake Urmia shows lower water redness in July 18 compared to April 23, 2016.
  } else {
    console.log('B'); // No.
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
